package main

import "fmt"

var ans [][]string
var path []string
var ansTop, pathTop int

func copyPath(n int) {
	tempPath := make([]string, pathTop)
	for i := 0; i < pathTop; i++ {
		tempPath[i] = path[i]
	}
	ans = append(ans, tempPath)
}

func isValid(x, y, n int) bool {
	for i := 0; i < n; i++ {
		if path[y][i] == 'Q' || path[i][x] == 'Q' {
			return false
		}
	}

	i, j := y-1, x-1
	for i >= 0 && j >= 0 {
		if path[i][j] == 'Q' {
			return false
		}
		i--
		j--
	}

	i, j = y+1, x+1
	for i < n && j < n {
		if path[i][j] == 'Q' {
			return false
		}
		i++
		j++
	}

	i, j = y-1, x+1
	for i >= 0 && j < n {
		if path[i][j] == 'Q' {
			return false
		}
		i--
		j++
	}

	i, j = y+1, x-1
	for i < n && j >= 0 {
		if path[i][j] == 'Q' {
			return false
		}
		i++
		j--
	}
	return true
}

func backTracking(n, depth int) {
	if pathTop == n {
		copyPath(n)
		return
	}

	for i := 0; i < n; i++ {
		if isValid(i, depth, n) {
			row := []rune(path[depth])
			row[i] = 'Q'
			path[depth] = string(row)
			pathTop++

			backTracking(n, depth+1)

			row[i] = '.'
			path[depth] = string(row)
			pathTop--
		}
	}
}

func initPath(n int) {
	path = make([]string, n)
	for i := 0; i < n; i++ {
		row := make([]rune, n)
		for j := 0; j < n; j++ {
			row[j] = '.'
		}
		path[i] = string(row)
	}
}

func solveNQueens(n int) [][]string {
	ans = make([][]string, 0)
	path = make([]string, 0)
	ansTop, pathTop = 0, 0

	initPath(n)
	backTracking(n, 0)

	return ans
}
