// Global variables (simulated using closure or module pattern)
let ans = [];
let path = [];
let ansTop = 0;
let pathTop = 0;

function copyPath(n) {
    const tempPath = [];
    for (let i = 0; i < pathTop; ++i) {
        const row = path[i].slice(); // shallow copy of string/array
        tempPath.push(row);
    }
    ans[ansTop++] = tempPath;
}

function isValid(x, y, n) {
    // Check row and column
    for (let i = 0; i < n; ++i) {
        if (path[y][i] === 'Q' || path[i][x] === 'Q') {
            return false;
        }
    }

    // Check upper-left diagonal
    let i = y - 1, j = x - 1;
    while (i >= 0 && j >= 0) {
        if (path[i][j] === 'Q') return false;
        --i; --j;
    }

    // Check lower-right diagonal
    i = y + 1, j = x + 1;
    while (i < n && j < n) {
        if (path[i][j] === 'Q') return false;
        ++i; ++j;
    }

    // Check upper-right diagonal
    i = y - 1, j = x + 1;
    while (i >= 0 && j < n) {
        if (path[i][j] === 'Q') return false;
        --i; ++j;
    }

    // Check lower-left diagonal
    i = y + 1, j = x - 1;
    while (i < n && j >= 0) {
        if (path[i][j] === 'Q') return false;
        ++i; --j;
    }

    return true;
}

function backTracking(n, depth) {
    if (pathTop === n) {
        copyPath(n);
        return;
    }

    for (let i = 0; i < n; ++i) {
        if (isValid(i, depth, n)) {
            path[depth][i] = 'Q';
            pathTop++;

            backTracking(n, depth + 1);

            path[depth][i] = '.';
            pathTop--;
        }
    }
}

function initPath(n) {
    path = Array(n).fill(null).map(() => Array(n).fill('.'));
}

function solveNQueens(n) {
    ans = [];
    path = [];
    ansTop = pathTop = 0;

    initPath(n);
    backTracking(n, 0);

    // Return value simulates C's returnSize and returnColumnSizes
    // In JS, we just return the result array; column sizes are all n
    return ans;
}
