        "code": "def main(readme_content):\n    import re\n    \n    # Extract purpose\n    purpose = re.search(r'#\\s*(.*)', readme_content, re.IGNORECASE)\n    purpose = purpose.group(1).strip() if purpose else ''\n    \n    # Extract technologies\n    technologies = re.findall(r'\\*\\s*([\\w\\s\\-]+)', readme_content)\n    technologies = list(set(technologies))  # Remove duplicates\n    \n    # Extract use cases\n    use_cases = re.findall(r'##\\s*Use Cases\\s*\\n\\n(.*?)\\n\\n', readme_content, re.DOTALL)\n    use_cases = [uc.strip() for uc in use_cases[0].split('\\n\\n') if uc.strip()] if use_cases else []\n    \n    # Extract notable features\n    notable_features = re.findall(r'##\\s*Notable Features\\s*\\n\\n(.*?)\\n\\n', readme_content, re.DOTALL)\n    notable_features = [nf.strip() for nf in notable_features[0].split('\\n\\n') if nf.strip()] if notable_features else []\n    \n    return {\n        'purpose': purpose,\n        'technologies': technologies,\n        'use_cases': use_cases,\n        'notable_features': notable_features\n    }"
